@router.post("/checkout/intents/{intent_pk}/capture")
async def capture_payment_intent(
    intent_pk: str,
    current_user: User = Depends(get_current_user),
    gateway: PaymentGatewayClient = Depends(get_payment_gateway)
):
    try:
        intent = PaymentIntentRecord.get(intent_pk)
    except NotFoundError:
        raise HTTPException(status_code=404, detail="Payment intent not found")

    if intent.merchant_id != current_user.merchant_id:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized to capture payment intent of another merchant")

    capture_res = await gateway.capture_charge(
        charge_id=intent.charge_id,
        amount=intent.amount_cents
    )
    intent.status = "CAPTURED"
    intent.save()

    return {"status": "captured", "intent_pk": intent.pk, "txn_id": capture_res.txn_id}
